package com.bank.qa.bug;

// The context that turns "cannot reproduce" into a deterministic repro.
class ReproBundle {
    private final String environment;  // OS, browser+version, which env
    private final String appVersion;   // exact build
    private final String testData;     // exact account IDs + amounts + state
    private final String steps;        // precise ordered steps
    private final String evidence;     // logs, video, HAR/network trace

    ReproBundle(String environment, String appVersion, String testData,
                String steps, String evidence) {
        this.environment = environment; this.appVersion = appVersion;
        this.testData = testData; this.steps = steps; this.evidence = evidence;
    }

    boolean isComplete() {
        return environment != null && appVersion != null && testData != null
            && steps != null && evidence != null;
    }

    @Override public String toString() {
        return "env=" + environment + "; ver=" + appVersion + "; data=" + testData
             + "; steps=" + steps + "; evidence=" + evidence;
    }
}
