package com.bank.qa.bug;

// A defect tracks its current state and its reproduction bundle.
class Defect {
    private final String id;
    private final String summary;
    private BugState state = BugState.NEW;
    private ReproBundle bundle;

    Defect(String id, String summary) { this.id = id; this.summary = summary; }

    String getId() { return id; }
    String getSummary() { return summary; }
    BugState getState() { return state; }
    void setState(BugState s) { this.state = s; }
    ReproBundle getBundle() { return bundle; }
    void attachBundle(ReproBundle b) { this.bundle = b; }
}
