package com.bank.qa.bug;

import java.util.logging.*;

public class BugLifecycleDemo {
    private static final Logger log = Logger.getLogger(BugLifecycleDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BugLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        BugWorkflow wf = new BugWorkflow();

        // Happy path defect
        Defect happy = new Defect("BUG-201", "Transfer shows wrong balance");
        log.info("=== Happy path ===");
        wf.transition(happy, BugState.ASSIGNED);
        wf.transition(happy, BugState.OPEN);
        wf.transition(happy, BugState.FIXED);
        wf.transition(happy, BugState.RETEST);
        wf.transition(happy, BugState.VERIFIED);
        wf.transition(happy, BugState.CLOSED);

        // Cannot-reproduce path
        Defect nr = new Defect("BUG-202", "Intermittent debit failure on dormant account");
        log.info("=== Cannot-reproduce path ===");
        wf.transition(nr, BugState.ASSIGNED);
        wf.transition(nr, BugState.OPEN);
        wf.transition(nr, BugState.NOT_REPRODUCIBLE);

        // Tester tries to push back WITHOUT a bundle -> blocked
        wf.transition(nr, BugState.OPEN);

        // Tester attaches the exact context -> now deterministic
        nr.attachBundle(new ReproBundle(
            "macOS 14.5, Chrome 128, STAGING",
            "online-banking 3.14.2 build 8821",
            "account=SAV2001 (dormant>180d), amount=50000.00, payee=CUR3001",
            "1.login rajesh 2.open transfers 3.select dormant SAV2001 4.enter 50000 5.submit",
            "video rec-202.mp4; server log traceId=abc-202; network HAR har-202.json"));
        log.info("[BUG-202] attached complete repro bundle: " + nr.getBundle());
        wf.transition(nr, BugState.OPEN);  // now allowed
        wf.transition(nr, BugState.FIXED);
    }
}

